  function applyLocale(lang){document.documentElement.lang=lang;document.documentElement.dir=lang==='en'?'ltr':'rtl';localStorage.setItem('gc-language',lang);const labels={ckb:'کوردی',ar:'العربية',en:'English'};const el=$('#gcLanguageLabel');if(el)el.textContent=labels[lang]||labels.ckb}
