  async function saveNotifications(){const msg=$('#gcNotificationMsg'),b=$('#gcSaveNotifications');b.disabled=true;msg.textContent='…';try{await api('POST',{action:'update_notification_preferences',data:{email_enabled:$('#gcEmailNotify').checked,whatsapp_enabled:$('#gcWhatsappNotify').checked,sms_enabled:false,in_app_enabled:$('#gcInApp').checked}});msg.textContent='ڕێکخستنەکانی ئاگادارکردنەوە پاشەکەوت کران.'}catch(e){msg.textContent=e.message||'پاشەکەوت نەکرا.'}finally{b.disabled=false}}
  function install(){if($('#gcAccountSettings'))return;const section=document.createElement('section');section.id='gcAccountSettings';section.className='gc-account-shell';const heading=document.createElement('div');heading.className='portal-section-heading';heading.innerHTML='<span>ACCOUNT CONTROL</span><h2>هەژماری من</h2><p>پڕۆفایل، پاراستن، زمان، ڕووناکی و پارەدان لە یەک شوێن.</p>';section.appendChild(heading);const anchor=document.querySelector('.portal-section-heading');anchor?.parentNode?.insertBefore(section,anchor.nextSibling);if(!anchor){document.querySelector('main')?.prepend(section)}loadProfile();}
